    const pe = parseDurationEnd(shot.duration || '');
    const videoPromptOriginal = [
      'Scene: ' + (shot.scene_setting || ''),
      'Action: ' + (shot.visual_action || ''),
      'Camera: ' + (shot.camera_movement || ''),
      'Product state: ' + (shot.product_state || ''),
      'Expression: ' + (shot.expression_focus || ''),
      'Voiceover (local): ' + (shot.optional_voiceover_local || ''),
      'Continuity: ' + (shot.continuity_requirements || ''),
    ].join(' ');

    const videoPrompt = [
      'Use the provided storyboard panel image as the exact first frame for this image-to-video clip.',
      'Create a realistic TikTok UGC-style ecommerce product video clip, vertical 9:16, natural handheld smartphone footage, natural light, real-life environment.',
      'Animate only small, natural movement from the visible first frame. Keep the same person identity, face, hairstyle, outfit, body proportion, product shape, product color, material, size, and usage logic.',
      'Keep the product as the visual center. Do not redesign the product. Do not change the background into a different location.',
      'Camera movement should be subtle and stable: small handheld sway, slight push-in, slight tilt, or gentle follow movement only.',
      'Do not add text, captions, subtitles, UI, watermark, logo overlays, stickers, extra fingers, distorted hands, product morphing, face morphing, or sudden scene cuts.',
      'Stage: ' + (shot.stage || ''),
      'Shot order: ' + (panelIndex + 1) + ' of ' + layoutForPanels.panels + '.',
      'Local voiceover reference only, do not render on-screen text: ' + (shot.optional_voiceover_local || ''),
      'Continuity reference: ' + (shot.continuity_requirements || ''),
    ].join(' ');

    const fileName =
      'panel_' +
      (scriptRow.project_id || json.project_id || 'proj') +
      '_' +
      (shot.shot_id || 'shot_' + (panelIndex + 1)) +
      '_9x16.' +
      outputExtension;

    const fullFileName =
      'panel_full_' +
      (scriptRow.project_id || json.project_id || 'proj') +
      '_' +
      (shot.shot_id || 'shot_' + (panelIndex + 1)) +
      '_' +
      Date.now() +
      '.' +
      outputExtension;
    const fullPath = path.join(panelCacheDir, fullFileName);
    fs.writeFileSync(fullPath, tileBuf);

    const previewFileName =
      'panel_preview_' +
      (scriptRow.project_id || json.project_id || 'proj') +
      '_' +
      (shot.shot_id || 'shot_' + (panelIndex + 1)) +
      '_' +
      Date.now() +
      '.jpg';
    const previewPath = path.join(panelCacheDir, previewFileName);
    fs.writeFileSync(previewPath, previewBuf);
    const previewUrl = reviewAssetBaseUrl + '/' + encodeURIComponent(previewFileName);
    out.push({
      json: {
        project_id: scriptRow.project_id || json.project_id || '',
        product_name: scriptRow.product_name || '',
        shot_id: shot.shot_id || '',
        shot_order: panelIndex + 1,
        panel_index: panelIndex,
        stage: shot.stage || '',
        duration: shot.duration || '',
        duration_start_sec: pe ? pe.start : null,
        duration_end_sec: pe ? pe.end : null,
        total_panels: layoutForPanels.panels,
        grid_rows: layoutForPanels.rows,
        grid_cols: layoutForPanels.cols,
        review_round: Number($('组装NanoBanana执行字段').first()?.json?.review_round || json.review_round || 1),
        auto_reconciled_storyboard: false,
        video_prompt: videoPrompt,
        video_prompt_original_zh: videoPromptOriginal,
        panel_file_name: fileName,
        panel_image_path: fullPath,
        panel_preview_path: previewPath,
        panel_preview_url: previewUrl,
        panel_mime_type: outputMimeType,
        panel_preview_mime_type: 'image/jpeg',
      },
    });
    panelIndex++;
  }
}

return out;

const fs = require('fs');
const path = require('path');

const row = $input.first().json || {};
const PROJECT_ROOT = require('process').env.PROJECT_ROOT || require('path').join(require('os').homedir(), 'Downloads', 'tiktok-n8n-workflow-pack');
const cacheDir = require('path').join(PROJECT_ROOT, '.n8n-local-cache', 'nanobanana');
fs.mkdirSync(cacheDir, { recursive: true });

const projectId =
  row.project_id ||
  $('本地图片转Gemini输入').first()?.json?.project_id ||
  $('Nano前_轻量上下文').first()?.json?.project_id ||
  'proj';

const mimeType = row.image_mime_type || 'image/jpeg';
const extension = row.file_extension || (mimeType.includes('png') ? 'png' : 'jpg');
const base64Data = row.image_base64 || '';

if (!base64Data) {
  throw new Error('NanoBanana 结果落盘失败：未找到 image_base64');
}

const fileName = 'storyboard_' + projectId + '_' + Date.now() + '.' + extension;
const absolutePath = path.join(cacheDir, fileName);
fs.writeFileSync(absolutePath, Buffer.from(base64Data, 'base64'));

return [
  {
    json: {
      project_id: projectId,
      storyboard_image_path: absolutePath,
      storyboard_image_mime_type: mimeType,
      storyboard_file_extension: extension,
      storyboard_file_name: fileName,
      storyboard_cached_at: new Date().toISOString(),
    },
  },
];

const fs = require('fs');
const path = require('path');

const items = $input.all();
if (!items.length) {
  throw new Error('分镜确认打包：未收到任何裁切分镜');
}

const PROJECT_ROOT = require('process').env.PROJECT_ROOT || require('path').join(require('os').homedir(), 'Downloads', 'tiktok-n8n-workflow-pack');
const reviewContextDir = require('path').join(PROJECT_ROOT, '.n8n-local-cache', 'review-context');
fs.mkdirSync(reviewContextDir, { recursive: true });

function esc(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const first = items[0].json || {};
const projectId = first.project_id || 'run';
const productName = first.product_name || '';
const reviewRound = Number(first.review_round || 1);
const panels = items.map((item) => ({ ...(item.json || {}) }));

const contextFileName =
  'review_context_' +
  String(projectId || 'run').replace(/[^a-zA-Z0-9_-]+/g, '_') +
  '_' +
  reviewRound +
  '_' +
  Date.now() +
  '.json';
const contextPath = path.join(reviewContextDir, contextFileName);
fs.writeFileSync(
  contextPath,
  JSON.stringify(
    {
      project_id: projectId,
      product_name: productName,
      creative_mode: first.creative_mode || '',
      concept_context_path: first.concept_context_path || '',
      panel_count: panels.length,
      review_round: reviewRound,
      panel_review_pack: panels,
    },
    null,
    2,
  ),
);

let cards = '';
for (const panel of panels) {
  const title = esc(panel.shot_id || 'shot_' + (panel.shot_order || ''));
  const meta = esc(
    [
      panel.shot_order != null ? '顺序:' + panel.shot_order : '',
      panel.stage || '',
      panel.duration || '',
    ]
      .filter(Boolean)
      .join(' | '),
  );
  const prompt = esc(panel.video_prompt || '');
  const previewUrl = esc(panel.panel_preview_url || '');
  cards +=
    '<div>' +
    '<h3>' +
    title +
    '</h3>' +
    '<p>' +
    meta +
    '</p>' +
    (previewUrl
      ? '<p><img src="' + previewUrl + '" alt="' + title + '" width="220" /></p>'
      : '<p>预览图暂不可用，请根据镜头编号核对。</p>') +
    '<p><strong>对应视频提示词</strong></p>' +
    '<pre>' +
    prompt +
    '</pre>' +
    '<hr />' +
    '</div>';
}

const reviewHtml =
  '<div>' +
  '<p><strong>请检查每张切割后的分镜图与对应提示词是否匹配。</strong></p>' +
  '<p>如果全部合适，选择“确认通过”。如果有问题，选择“需要重做”，并填写需要重做的镜头编号，例如 <code>shot_2, shot_5</code>，再写清楚修改意见。</p>' +
  '<p>当前轮次：第 ' +
  reviewRound +
  ' 轮，项目：' +
  esc(projectId) +
  (productName ? '，产品：' + esc(productName) : '') +
  '。</p>' +
  cards +
  '</div>';

return [
  {
    json: {
      project_id: projectId,
      product_name: productName,
      panel_count: panels.length,
      review_round: reviewRound,
      review_context_path: contextPath,
      review_form_html: reviewHtml,
    },
  },
];
